import re
from taf.ul.sc.rtg.workstation import Workstation    # type: ignore


def create_devices_from_regex(pattern):
    """
    Create devices based on regex pattern.

    :param pattern: Regular expression pattern for which will be created device(s).
    :return: List with names of created devices.
    """
    for device_regex, creation_function in _device_creation_functions.items():
        if re.search(device_regex, pattern) or pattern == device_regex:
            created_devices = creation_function()
            device_names = [device.name for device in created_devices]
            break
    else:
        raise KeyError(
            "There are not device creation function for {} regex. Contact PAF dev team to add it.".format(pattern))
    return device_names


def _create_rtg_schmmi_devices():
    rtg_ws = Workstation()
    return rtg_ws.create_schmmi_devices()


_device_creation_functions = {
    'RTG_SCHMMI_\\d+': _create_rtg_schmmi_devices
}
